public class Time {
    public static void main(String[] args) {
        int startHour = 15;
        int startMinute = 10;
        int startSecond = 30;

        int currentHour = 15;
        int currentMinute = 17;
        int currentSecond = 51;

        int startSeconds = startHour * 3600 + startMinute * 60 + startSecond;
        int currentSeconds = currentHour * 3600 + currentMinute * 60 + currentSecond;
        int secondsPassed = currentSeconds - startSeconds;
        int secondsLeft = 24 * 3600 - currentSeconds;

        System.out.println(secondsPassed + " seconds have passed since midnight.");
        System.out.println(secondsLeft + " seconds are left until midnight.");
        System.out.println(secondsPassed + " seconds have passed.");
    }
}
