public class Time {
    public static void main(String[] args) {
        // Fixed values from the task
        int startHour = 15, startMinute = 10, startSecond = 30;
        int currentHour = 15, currentMinute = 17, currentSecond = 51;

        // a) Variables for the start time
        int startSecondsSinceMidnight = startHour * 3600 + startMinute * 60 + startSecond;

        // b) Variables for the current time
        int currentSecondsSinceMidnight = currentHour * 3600 + currentMinute * 60 + currentSecond;

        // c) Seconds passed since midnight
        int secondsPassed = currentSecondsSinceMidnight;
        System.out.println(secondsPassed + " seconds have passed since midnight.");

        // d) Seconds left until midnight
        int secondsLeft = 24 * 3600 - currentSecondsSinceMidnight;
        System.out.println(secondsLeft + " seconds are left until midnight.");

        // e) Time elapsed from start to current time
        int timeElapsed = currentSecondsSinceMidnight - startSecondsSinceMidnight;
        System.out.println("Since I started with the task " + timeElapsed + " seconds have passed.");
    }
}
