public class Time {
    public static void main(String[] args) {
        // Task b: Define variables for the start time
        int startHour = 15;
        int startMinute = 10;
        int startSecond = 30;

        // Task c: Calculate seconds passed since midnight
        int secondsPassed = startHour * 3600 + startMinute * 60 + startSecond;
        System.out.println(secondsPassed + " seconds have passed since midnight.");

        // Task d: Calculate seconds left until midnight
        int secondsLeft = (23 - startHour) * 3600 + (59 - startMinute) * 60 + (59 - startSecond);
        System.out.println(secondsLeft + " seconds are left until midnight.");

        // Task e: Define variables for the current time
        int currentHour = 15;
        int currentMinute = 17;
        int currentSecond = 51;

        // Task e: Calculate seconds passed since the start time
        int secondsPassedSinceStart = (currentHour - startHour) * 3600 + (currentMinute - startMinute) * 60 + (currentSecond - startSecond);
        System.out.println("Since I started with the task " + secondsPassedSinceStart + " seconds have passed.");
    }
}
